import { readFileSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { MiaDataStore } from "../src/services/data-store";
const cases = JSON.parse(readFileSync(new URL("./fixtures/stabilize-data-roundtrip.json", import.meta.url), "utf8")) as { name: string; input: unknown; bytes: string }[];
// Expected bytes captured using the unmodified 1.4.26 data store, never regenerated by tests.
describe("1.4.26 load/save byte compatibility", () => {
  beforeEach(() => { vi.spyOn(crypto, "randomUUID").mockReturnValue("00000000-0000-4000-8000-000000000001"); });
  afterEach(() => { vi.restoreAllMocks(); });
  it.each(cases)("round-trips $name with identical serialized bytes", async ({ input, bytes }) => {
    let disk = structuredClone(input), saved = "";
    const store = new MiaDataStore({ loadData: async () => structuredClone(disk), saveData: async data => { saved = JSON.stringify(data, null, 2); disk = JSON.parse(saved); } });
    await store.load(); await store.updateSettings({});
    expect(saved).toBe(bytes);
    await store.load(); await store.updateSettings({});
    expect(saved).toBe(bytes);
  });
});
